def add_locale_copy():
    for locale in LOCALES:
        path = ROOT / 'src/i18n/locales' / locale / 'racePreparation.json'
        data = json.loads(path.read_text(encoding='utf-8'))
        data['screen'] = COPY[locale]
        path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')


def fix_component():
    src = COMPONENT.read_text(encoding='utf-8')

    if 'import appI18n from "../../i18n";' not in src:
        src = src.replace(
            'import { useTranslation } from "react-i18next";\n',
            'import { useTranslation } from "react-i18next";\nimport appI18n from "../../i18n";\n',
            1,
        )

    helper_anchor = 'const fullMonthLabels = ['
    helper_marker = 'function racePrepText('
    if helper_marker not in src:
        end = src.index('];', src.index(helper_anchor)) + 2
        helper = r'''

const RACE_PREP_LOCALES: Record<string, string> = {
  en: "en-GB",
  "sr-Latn": "sr-Latn-RS",
  de: "de-DE",
  hr: "hr-HR",
  es: "es-ES",
  it: "it-IT",
  fr: "fr-FR",
  ru: "ru-RU",
};

function racePrepText(key: string, options: Record<string, unknown> = {}): string {
  return String(appI18n.t(key, { ns: "racePreparation", ...options }));
}

function getRacePrepLocale(): string {
  const language = appI18n.resolvedLanguage || appI18n.language || "en";
  const normalized = language.startsWith("sr") ? "sr-Latn" : language.split("-")[0];
  return RACE_PREP_LOCALES[normalized] || "en-GB";
}

function localizedGameMonth(month: number, style: "short" | "long" = "short"): string {
  const safeMonth = Math.min(12, Math.max(1, Number(month) || 1));
  return new Intl.DateTimeFormat(getRacePrepLocale(), {
    month: style,
    timeZone: "UTC",
  }).format(new Date(Date.UTC(2026, safeMonth - 1, 1)));
}

function localizeRacePrepBackendText(value: unknown): string {
  const raw = String(value ?? "").trim();
  if (!raw) return raw;
  const exact: Record<string, string> = {
    "Race Ready": "screen.raceReady",
    Fit: "screen.fit",
    Leader: "riderRoles.teamLeader",
    Sprinter: "riderRoles.sprinter",
    Climber: "riderRoles.climber",
    Domestique: "riderRoles.helper",
    Breakaway: "riderRoles.breakawayRider",
    "Breakaway Rider": "riderRoles.breakawayRider",
    "All-rounder": "screen.allRounder",
    "Free Role": "screen.freeRole",
    "Follow Stage Role": "screen.followStageRole",
    "Default Race Setup": "screen.defaultRaceSetup",
    "Missing Stage Plans": "screen.missingStagePlans",
    "Missing Stage Plan": "screen.missingStagePlan",
    Open: "screen.statusOpenValue",
    Locked: "screen.statusLockedValue",
    "No Sport Director selected. Tactics execution may be weaker.": "screen.validationNoSportDirector",
    "No Mechanic selected. Mechanical and equipment support may be weaker.": "screen.validationNoMechanic",
    "No race-level assets selected.": "screen.validationNoAssets",
  };
  const exactKey = exact[raw];
  if (exactKey) return racePrepText(exactKey);

  const riderCount = raw.match(/^Selected rider count (\d+) is outside allowed range (\d+)[–-](\d+)\.$/);
  if (riderCount) {
    return racePrepText("screen.validationSelectedRiders", {
      count: riderCount[1], min: riderCount[2], max: riderCount[3],
    });
  }
  return raw;
}
'''
        src = src[:end] + helper + src[end:]

    # Add small missing value labels used by the generic backend localizer.
    # They are inserted into each locale below after the main copy table.

    # Localize the date functions without changing game-date semantics.
    src = src.replace(
        'return `S${parts.season} · ${monthLabels[parts.month - 1]} ${String(\n    parts.day,\n  ).padStart(2, "0")}`;',
        'return `S${parts.season} · ${localizedGameMonth(parts.month, "short")} ${String(\n    parts.day,\n  ).padStart(2, "0")}`;',
    )
    src = src.replace(
        'return `Season ${parts.season} - ${\n    fullMonthLabels[parts.month - 1]\n  } ${String(parts.day).padStart(2, "0")}`;',
        'return `${racePrepText("screen.season")} ${parts.season} - ${localizedGameMonth(parts.month, "long")} ${String(parts.day).padStart(2, "0")}`;',
    )
    src = src.replace('date.toLocaleDateString(undefined, {', 'date.toLocaleDateString(getRacePrepLocale(), {')
    src = src.replace('const monthLabel = monthLabels[date.getUTCMonth()] ?? "—";', 'const monthLabel = localizedGameMonth(date.getUTCMonth() + 1, "short");')

    # Backend quote validation text must never leak English into non-English UI.
    src = src.replace('{error}\n', '{localizeRacePrepBackendText(error)}\n')
    src = src.replace('{warning}\n', '{localizeRacePrepBackendText(warning)}\n')
    src = re.sub(r'\{([A-Za-z_$][\w$.]*\.readiness_label)\}', r'{localizeRacePrepBackendText(\1)}', src)
    src = re.sub(r'\{([A-Za-z_$][\w$.]*\.recommended_action)\}', r'{localizeRacePrepBackendText(\1)}', src)

    # Rider-card labels and values.
    src = src.replace('<span>Role: {String(option.assigned_role ?? "—")}</span>', '<span>{racePrepText("screen.role")}: {localizeRacePrepBackendText(option.assigned_role ?? "—")}</span>')
    src = src.replace('<span>Availability: {availabilityLabel}</span>', '<span>{racePrepText("screen.availability")}: {localizeRacePrepBackendText(availabilityLabel)}</span>')
    src = src.replace('Fatigue: {String(rider.fatigue ?? "—")} · Availability:{" "}\n              {availabilityLabel}', '{racePrepText("screen.fatigue")}: {String(rider.fatigue ?? "—")} · {racePrepText("screen.availability")}:{" "}\n              {localizeRacePrepBackendText(availabilityLabel)}')
    src = src.replace('Race Sharpness: {percent}/100 · {sharpness.race_sharpness_label}', 'Race Sharpness: {percent}/100 · {localizeRacePrepBackendText(sharpness.race_sharpness_label)}')
    src = src.replace('{percent}/100 · {sharpness.race_sharpness_label}', '{percent}/100 · {localizeRacePrepBackendText(sharpness.race_sharpness_label)}')
    src = src.replace('{sharpness.race_sharpness_message}', '{localizeRacePrepBackendText(sharpness.race_sharpness_message)}')

    # Simple visible JSX text nodes introduced by the newer Race Plan / Stage Plan UI.
    text_nodes = {
      'Starting freshness combines fatigue and race sharpness. High fatigue can lower the red bar even when sharpness is good.':'startingFreshnessHelp',
      'Race Plan Bonus Preview':'bonusTitle','Standardized Race Bonus Percentages':'bonusStandardized',
      'Race staff, race assets, and team policies are converted into these standardized race-engine percentage bonuses. Hover or click a card to see the source breakdown.':'bonusDescription',
      'details':'details','1. Rider Equipment Packages':'riderEquipmentPackages','Choose one equipment package for each rider for this stage.':'chooseEquipmentPackage',
      '2. Stage Roles':'stageRoles','Rider stage roles':'riderStageRoles','3. Individual Tactics':'individualTactics',
      'Phases 1–3 contain general race orders. Phase 4 contains finish preparation, sprint-train and lead-out orders.':'phaseDescription',
      'Do not forget to save this stage. These phase commands are saved only for the selected stage.':'saveStageWarning',
      'RIDER':'rider','4. Stage Race Supplies':'stageRaceSupplies','Stage supply setup':'stageSupplySetup','STAGE SUPPLIES':'stageSupplies',
      'Stage stock check':'stageStockCheck','Plan only':'planOnly','5. Final Stage Calculation':'finalStageCalculation',
      'Race Plan bonus total':'racePlanBonusTotal','Equipment bonus direction':'equipmentBonusDirection','Rain jacket effect':'rainJacketEffect',
      'Race Plan bonuses':'racePlanBonuses','Stage supplies':'stageSuppliesSummary','Bidons needed':'bidonsNeeded','Energy gels needed':'energyGelsNeeded',
      'Nutrition packs needed':'nutritionPacksNeeded','Race jerseys needed':'raceJerseysNeeded','Rain jackets needed':'rainJacketsNeeded',
      'Selected stage save':'selectedStageSave','Stage Plan lock':'stagePlanLock','Not saved yet':'notSavedYet',
      'SELECTED STAGE PROFILE':'selectedStageProfile','DATE':'date','ROUTE':'route','PROFILE':'profile','DISTANCE':'distance','STAGE WEATHER':'stageWeather',
      'Temp':'temp','Wind':'wind','Rain':'rain','Open Race Page':'openRacePage',
    }
    for english, key in text_nodes.items():
        pattern = re.compile(r'>\s*' + re.escape(english) + r'\s*<')
        src = pattern.sub('>{racePrepText("screen.' + key + '")}<', src)

    # Exact quoted UI strings / ternaries.
    quoted = {
      '"Time-trial engine preview for equipment, support, fatigue, weather and pacing risk."':'racePrepText("screen.ttFinalCalcDesc")',
      '"Team-level engine preview for this exact stage setup: Race Plan bonuses, equipment, supplies, weather and risk factors."':'racePrepText("screen.finalCalcDesc")',
      '"Choose one clear role for each rider. Detailed race orders are set below in Individual Tactics."':'racePrepText("screen.chooseRole")',
      '"This stage plan is still open and can be edited until the lock time is reached."':'racePrepText("screen.openLockHint")',
      '"This stage plan is locked because the current game time is already at or after the stage lock time."':'racePrepText("screen.lockedLockHint")',
    }
    for old, new in quoted.items():
        src = src.replace(old, new)

    # Common button strings (safe: these phrases are UI only in this page).
    src = re.sub(r'>\s*Ask Sport Director\s*<', '>{racePrepText("screen.askSportDirector")}<', src)
    src = re.sub(r'>\s*Save\s*<', '>{racePrepText("screen.save")}<', src)

    # Labels with interpolation.
    src = src.replace('<span>Lock time: {lockInfo.lockAtLabel}</span>', '<span>{racePrepText("screen.lockTime")}: {lockInfo.lockAtLabel}</span>')
    src = src.replace('Lock time: {lockInfo.lockAtLabel}', '{racePrepText("screen.lockTime")}: {lockInfo.lockAtLabel}')
    src = src.replace('Stage start: {lockInfo.stageStartLabel}', '{racePrepText("screen.stageStart")}: {lockInfo.stageStartLabel}')

    # Localize visible data labels returned from backend/options when rendered.
    src = src.replace('{availabilityLabel}', '{localizeRacePrepBackendText(availabilityLabel)}')
    src = src.replace('{option.label}', '{localizeRacePrepBackendText(option.label)}')
    src = src.replace('{role.label}', '{localizeRacePrepBackendText(role.label)}')
    src = src.replace('{stageRole.label}', '{localizeRacePrepBackendText(stageRole.label)}')
    src = src.replace('{getStageProfileLabel(stage)}', '{localizeRacePrepBackendText(getStageProfileLabel(stage))}')

    COMPONENT.write_text(src, encoding='utf-8')


def add_helper_values():
    values = {
      'en': {'allRounder':'All-rounder','statusOpenValue':'Open','statusLockedValue':'Locked'},
      'sr-Latn': {'allRounder':'Svestrani vozač','statusOpenValue':'Otvoren','statusLockedValue':'Zaključan'},
      'de': {'allRounder':'Allrounder','statusOpenValue':'Offen','statusLockedValue':'Gesperrt'},
      'hr': {'allRounder':'Svestrani vozač','statusOpenValue':'Otvoren','statusLockedValue':'Zaključan'},
      'es': {'allRounder':'Todoterreno','statusOpenValue':'Abierto','statusLockedValue':'Bloqueado'},
      'it': {'allRounder':'Ciclista completo','statusOpenValue':'Aperto','statusLockedValue':'Bloccato'},
      'fr': {'allRounder':'Polyvalent','statusOpenValue':'Ouvert','statusLockedValue':'Verrouillé'},
      'ru': {'allRounder':'Универсал','statusOpenValue':'Открыт','statusLockedValue':'Заблокирован'},
    }
    for locale in LOCALES:
        path = ROOT / 'src/i18n/locales' / locale / 'racePreparation.json'
        data = json.loads(path.read_text(encoding='utf-8'))
        data.setdefault('screen', {}).update(values[locale])
        path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')


if __name__ == '__main__':
    add_locale_copy()
    add_helper_values()
    fix_component()
    print('Race Preparation localization fixer applied for 8 locales.')
